#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

static void bits_of(double d) {
    uint64_t b;
    memcpy(&b, &d, sizeof b);
    printf("    0x%016llX\n", (unsigned long long)b);
}

int main(void) {
    double zero = 0.0, nzero = -0.0;
    double inf = 1.0 / zero, ninf = -1.0 / zero;
    double nan = zero / zero;

    printf("=== IEEE 754 special values (double) ===\n");
    printf("  +0.0 bits:");      bits_of(zero);
    printf("  -0.0 bits:");      bits_of(nzero);
    printf("  infinity bits:");  bits_of(inf);
    printf("\n");
    printf("  0.0 == -0.0            -> %s   (they compare equal)\n", (zero == nzero) ? "true" : "false");
    printf("  signbit(-0.0)          -> %s   (yet the sign is still recorded)\n",
           signbit(nzero) ? "true" : "false");
    printf("  1.0 / 0.0              -> %a\n", inf);
    printf("  -1.0 / 0.0             -> %a\n", ninf);
    printf("  0.0 / 0.0              -> %a\n", nan);

    printf("\n=== NaN never equals anything ===\n");
    printf("  nan == nan             -> %s\n", (nan == nan) ? "true" : "false");
    printf("  nan != nan             -> %s   (the classic NaN test)\n", (nan != nan) ? "true" : "false");
    printf("  nan != 1.0             -> %s\n", (nan != 1.0) ? "true" : "false");
    printf("  isnan(nan)             -> %s\n", isnan(nan) ? "true" : "false");
    printf("  isnan(inf)             -> %s\n", isnan(inf) ? "true" : "false");

    printf("\n=== propagation ===\n");
    printf("  inf + 1.0              -> %a\n", inf + 1.0);
    printf("  inf - inf              -> %a   (invalid operation)\n", inf - inf);
    printf("  0.0 * inf              -> %a   (invalid operation)\n", zero * inf);
    printf("  inf / inf              -> %a\n", inf / inf);
    printf("  1.0 / inf              -> %a\n", 1.0 / inf);

    printf("\nrule: comparisons with NaN are all false EXCEPT '!=' which is true\n");
    printf("so test with isnan(x) or (x != x); never write  x == NAN\n");
    return 0;
}
